static class FormFactory
{
    public static IForm Erzeuge(
        string art, double m) =>
        art switch
        {
          "kreis" => new Kreis(m),
          "quadrat" => new Quadrat(m),
          _ => throw new
            ArgumentException(
              $"Unbekannt: {art}")
        };
}

IForm f = FormFactory.Erzeuge("kreis", 2);
Console.WriteLine(
    f.Flaeche().ToString("F2")); // 12.57

sealed class Konfig
{
    private static readonly
        Lazy<Konfig> lazy =
            new(() => new Konfig());
    public static Konfig Instanz
        => lazy.Value;
    private Konfig() { }
}

var a = Konfig.Instanz;
var b = Konfig.Instanz;
Console.WriteLine(
    ReferenceEquals(a, b)); // True

class PizzaBuilder
{
    private int groesse;
    private readonly List<string>
        belag = new();
    public PizzaBuilder Groesse(int cm)
    { groesse = cm; return this; }
    public PizzaBuilder Mit(string z)
    { belag.Add(z); return this; }
    public Pizza Build()
    {
        if (groesse <= 0)
            throw new
              InvalidOperationException(
                "Größe fehlt");
        return new Pizza {
            Groesse = groesse,
            Belag = new(belag) };
    }
}

var pizza = new PizzaBuilder()
    .Groesse(32)
    .Mit("Schinken")
    .Mit("Pilze")
    .Build();
Console.WriteLine(pizza);
// 32 cm: Schinken, Pilze

